import heapq

def mexAfterUpdates(nums, updates):
    nums = list(nums)
    n = len(nums)
    cnt = [0] * (n + 2)
    for x in nums:
        if x <= n:
            cnt[x] += 1
    heap = [v for v in range(n + 1) if cnt[v] == 0]
    heapq.heapify(heap)
    out = []
    for i, v in updates:
        old = nums[i]
        if old <= n:
            cnt[old] -= 1
            if cnt[old] == 0:
                heapq.heappush(heap, old)
        nums[i] = v
        if v <= n:
            cnt[v] += 1
        while cnt[heap[0]] > 0:
            heapq.heappop(heap)
        out.append(heap[0])
    return out
